// 1405.5.18η — fix exit close after backup + autosave green dot
(function(){
  // CSS
  if(!document.getElementById('autosave-dot-css')){
    var st = document.createElement('style');
    st.id = 'autosave-dot-css';
    st.textContent = '#autosave-dot{position:fixed;bottom:16px;left:16px;width:12px;height:12px;border-radius:50%;background:#16a34a;opacity:0;pointer-events:none;z-index:99999;box-shadow:0 0 0 0 rgba(22,163,74,.55);transition:opacity .15s ease;}#autosave-dot.on{opacity:1;animation:autosavePulse 1.4s ease-out;}@keyframes autosavePulse{0%{transform:scale(.85);box-shadow:0 0 0 0 rgba(22,163,74,.65);}40%{transform:scale(1.2);box-shadow:0 0 0 8px rgba(22,163,74,.15);}100%{transform:scale(1);box-shadow:0 0 0 0 rgba(22,163,74,0);}}body.sb-dock #autosave-dot{bottom:72px;}';
    document.head.appendChild(st);
  }
  if(!document.getElementById('autosave-dot')){
    var d = document.createElement('div');
    d.id = 'autosave-dot';
    d.title = 'ذخیره خودکار';
    document.body.appendChild(d);
  }

  window.flashAutosaveDot = function(){
    var dot = document.getElementById('autosave-dot');
    if(!dot){
      dot = document.createElement('div');
      dot.id = 'autosave-dot';
      document.body.appendChild(dot);
    }
    dot.classList.remove('on');
    void dot.offsetWidth;
    dot.classList.add('on');
    clearTimeout(window._autosaveDotTimer);
    window._autosaveDotTimer = setTimeout(function(){ try{ dot.classList.remove('on'); }catch(_e){} }, 1800);
  };

  window._showExitCloseHint = function(){
    try{
      var old = document.getElementById('exit-close-hint');
      if(old) old.remove();
      var ov = document.createElement('div');
      ov.id = 'exit-close-hint';
      ov.style.cssText = 'position:fixed;inset:0;z-index:100000;background:rgba(15,23,42,.72);display:flex;align-items:center;justify-content:center;padding:20px';
      ov.innerHTML = '<div style="background:#fff;color:#111;border-radius:14px;padding:22px 20px;max-width:420px;width:100%;text-align:center;line-height:1.9;font-family:Tahoma,sans-serif">'
        + '<div style="font-size:18px;font-weight:800;margin-bottom:8px">بک‌آپ/خروج انجام شد</div>'
        + '<div style="font-size:13px;color:#555;margin-bottom:14px">مرورگر اجازه بستن خودکار این تب را نداد.<br>لطفاً با <b>Ctrl+W</b> ببندید.</div>'
        + '<button style="width:100%;padding:10px;border:0;border-radius:8px;background:#2563eb;color:#fff;font-weight:700;cursor:pointer" onclick="try{window.close();}catch(e){}">تلاش دوباره برای بستن</button>'
        + '</div>';
      document.body.appendChild(ov);
    }catch(_e){}
  };

  window._doExit = function(){
    try{ if(typeof clearDirty==='function') clearDirty(); }catch(_e){}
    try{ window.open('', '_self'); window.close(); }catch(e){}
    setTimeout(function(){
      try{ if(!document.hidden) _showExitCloseHint(); }catch(_e2){ _showExitCloseHint(); }
    }, 350);
  };

  window.exitWithBackup = async function(){
    var modal = document.getElementById('exit-modal');
    if(modal) modal.classList.remove('open');
    try{
      if(typeof exportData==='function') await exportData();
      if(typeof doAutoSave==='function' && ((typeof autoSaveFileHandle!=='undefined' && autoSaveFileHandle) || (typeof autoSaveDirHandle!=='undefined' && autoSaveDirHandle))){
        try{ await doAutoSave(true); }catch(_as){}
      }
      if(typeof clearDirty==='function') clearDirty();
      if(typeof ntf==='function') ntf('بک‌آپ گرفته شد — در حال بستن...','ok');
      _doExit();
    }catch(e){
      if(typeof ntf==='function') ntf('بک‌آپ خطا داد؛ بسته نشد','err');
      alert('بک‌آپ قبل از خروج ناموفق بود:\n'+(e && e.message ? e.message : e));
    }
  };

  window.exitWithoutBackup = function(){
    var modal = document.getElementById('exit-modal');
    if(modal) modal.classList.remove('open');
    if(typeof clearDirty==='function') clearDirty();
    _doExit();
  };

  // wrap updateAutoSaveUI to flash dot
  if(typeof updateAutoSaveUI==='function' && !window._sirmanUpdateAutoSaveUIWrappedEta){
    var _u = updateAutoSaveUI;
    updateAutoSaveUI = function(success, errMsg){
      try{ _u(success, errMsg); }catch(_e){}
      if(success){ try{ flashAutosaveDot(); }catch(_e2){} }
    };
    window._sirmanUpdateAutoSaveUIWrappedEta = true;
  }

  var btn = document.querySelector('#exit-modal .btn-p');
  if(btn && (btn.textContent||'').indexOf('بک')>=0) btn.textContent = '💾 بک‌آپ بگیر و ببند';
})();
